/**
 * ==============================================================================
 * HỆ THỐNG XỬ LÝ ĐĂNG KÝ & TỰ ĐỘNG XÁC NHẬN THANH TOÁN - "AI FOR STUDENT"
 * ==============================================================================
 * Link Google Sheet:
 * https://docs.google.com/spreadsheets/d/1nUqOXlny1-f8UnDFwOQcP6YdhEDgtB6LX0AhGcG6Qc8/edit?usp=sharing
 *
 * LUỒNG TỰ ĐỘNG HÓA 3 BƯỚC:
 * 1. Phụ huynh gửi form:
 *    - Ghi nhận vào Sheet (Trạng thái: "⏳ Chờ thanh toán").
 *    - Gửi mail tạm tính cho Phụ huynh (kèm mã QR VietinBank thanh toán học phí).
 *    - Gửi mail thông báo cho Thầy (kèm nút bấm "Xác Nhận Đã Thu Học Phí").
 * 2. Phụ huynh chuyển tiền thành công:
 *    - Thầy mở Gmail bấm vào nút "Xác Nhận Đã Thu Học Phí".
 * 3. Hệ thống kích hoạt tức thì:
 *    - Cập nhật Google Sheet thành "✅ ĐÃ THANH TOÁN".
 *    - Tự động gửi Thư Chúc Mừng Ghi Danh chính thức cho Phụ huynh kèm:
 *      + Lời chúc mừng cá nhân hóa theo Tên của bé.
 *      + Link truy cập nhóm Zalo lớp học: https://zalo.me/g/ivlwcpo2ke7krpwc843r
 *      + Ảnh thẻ mã QR nhóm Zalo "AI FOR TEEN - THỰC HỌC" sắc nét.
 * ==============================================================================
 */

// CẤU HÌNH HỆ THỐNG
var ADMIN_EMAIL = ""; // Điền email của Thầy để nhận thông báo (Nếu để trống, hệ thống tự động lấy email Gmail đang chạy script)
var BRAND_NAME = "AI FOR STUDENT - Chinh Phục Gemini & NotebookLM";
var ZALO_GROUP_LINK = "https://zalo.me/g/ivlwcpo2ke7krpwc843r";
var DEFAULT_WEBAPP_URL = "https://script.google.com/macros/s/AKfycbxEqeUORxqqE6og65nIFJD7WzqXHHEFApCws_rhDDQ-ug-1AGj6BojI-N7p5_nF0tyWuQ/exec";

// Chuỗi Base64 ảnh Thẻ QR Nhóm Zalo "AI FOR TEEN - THỰC HỌC"
var ZALO_GROUP_CARD_B64 = "";

/**
 * Lấy URL Web App hiện tại của Script
 */
function getWebAppUrl() {
  try {
    var url = ScriptApp.getService().getUrl();
    if (url && url.indexOf("/exec") !== -1) return url;
  } catch (e) {}
  return DEFAULT_WEBAPP_URL;
}

/**
 * Lấy email nhận thông báo của Thầy (Admin)
 */
function getAdminEmail() {
  if (ADMIN_EMAIL && ADMIN_EMAIL.indexOf("@") !== -1 && ADMIN_EMAIL !== "admin@aiforstudent.edu.vn") {
    return ADMIN_EMAIL;
  }
  try {
    var userEmail = Session.getEffectiveUser().getEmail();
    if (userEmail && userEmail.indexOf("@") !== -1) return userEmail;
  } catch (e) {}
  try {
    var userEmail2 = Session.getActiveUser().getEmail();
    if (userEmail2 && userEmail2.indexOf("@") !== -1) return userEmail2;
  } catch (e) {}
  return "thientran.ai@gmail.com";
}

/**
 * ==============================================================================
 * 1. XỬ LÝ YÊU CẦU GET (Khi Thầy bấm nút Xác Nhận Thanh Toán trong Gmail)
 * ==============================================================================
 */
function doGet(e) {
  var params = (e && e.parameter) ? e.parameter : {};
  
  // Khi Thầy bấm nút xác nhận thanh toán
  if (params.action === "confirm_payment") {
    return handleConfirmPayment(params.token, params.row);
  }

  // Trang mặc định kiểm tra trạng thái Web App
  return HtmlService.createHtmlOutput(
    "<!DOCTYPE html><html><head><meta charset='utf-8'><link href='https://fonts.googleapis.com/css2?family=Be+Vietnam+Pro:wght@600;800&display=swap' rel='stylesheet'></head><body style='font-family: \"Be Vietnam Pro\", sans-serif; text-align: center; padding: 50px 20px; color: #1e293b;'>" +
      "<h2 style='color: #0284c7;'>🚀 Hệ Thống Web App AI FOR STUDENT Đang Hoạt Động!</h2>" +
      "<p style='color: #64748b;'>Web App sẵn sàng tiếp nhận đơn đăng ký và xử lý xác nhận thanh toán tự động.</p>" +
    "</body></html>"
  ).setTitle("AI FOR STUDENT - Automation Service");
}

/**
 * ==============================================================================
 * 2. XỬ LÝ YÊU CẦU POST (Khi Phụ huynh bấm Đăng ký từ Landing Page)
 * ==============================================================================
 */
function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
    setupHeadersIfEmpty(sheet);

    var data;
    if (e.postData && e.postData.contents) {
      data = JSON.parse(e.postData.contents);
    } else if (e.parameter) {
      data = e.parameter;
    } else {
      throw new Error("Không có dữ liệu gửi lên.");
    }

    var timestamp = new Date();
    var formattedDate = Utilities.formatDate(timestamp, "GMT+7", "yyyy-MM-dd HH:mm:ss");

    var parentName = data.parentName || "Chưa có";
    var phone = data.phone || "Chưa có";
    var email = data.email || "";
    var studentInfo = data.studentInfo || "Chưa có";
    var studentCount = data.studentCount || 1;
    var selectedModules = data.selectedModules || "Trọn khóa 4 Module";
    var totalSessions = data.totalSessions || 10;
    var pricePerSession = data.pricePerSession || 300000;
    var totalPrice = data.totalPrice || 3000000;
    var totalSavings = data.totalSavings || 0;
    var note = data.note || "";
    var status = "⏳ Chờ thanh toán";
    var token = Utilities.getUuid(); // Mã bảo mật dùng để xác nhận đơn

    // Ghi hàng mới vào Sheet
    sheet.appendRow([
      formattedDate,
      parentName,
      "'" + phone,
      email,
      studentInfo,
      studentCount,
      selectedModules,
      totalSessions,
      pricePerSession,
      totalPrice,
      totalSavings,
      note,
      status,
      token
    ]);

    var newRowIndex = sheet.getLastRow();
    var webAppUrl = getWebAppUrl();
    var confirmPaymentUrl = webAppUrl + "?action=confirm_payment&token=" + token + "&row=" + newRowIndex;

    // A. Gửi email thông báo kèm nút Xác Nhận cho Thầy (Admin)
    sendAdminRegistrationAlert({
      formattedDate: formattedDate,
      parentName: parentName,
      phone: phone,
      email: email,
      studentInfo: studentInfo,
      studentCount: studentCount,
      selectedModules: selectedModules,
      totalSessions: totalSessions,
      pricePerSession: pricePerSession,
      totalPrice: totalPrice,
      totalSavings: totalSavings,
      note: note,
      rowIndex: newRowIndex,
      confirmUrl: confirmPaymentUrl
    });

    // B. Gửi email xác nhận đăng ký tạm tính cho Phụ huynh (Kèm mã VietQR VietinBank)
    if (email && email.indexOf("@") !== -1) {
      sendParentRegistrationPendingEmail(email, {
        parentName: parentName,
        studentInfo: studentInfo,
        studentCount: studentCount,
        selectedModules: selectedModules,
        totalSessions: totalSessions,
        totalPrice: totalPrice,
        phone: phone
      });
    }

    return ContentService.createTextOutput(JSON.stringify({
      status: "success",
      message: "Đăng ký thành công! Dữ liệu đã lưu vào Google Sheet và thông báo đã gửi.",
      rowIndex: newRowIndex
    })).setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({
      status: "error",
      message: error.toString()
    })).setMimeType(ContentService.MimeType.JSON);

  } finally {
    lock.releaseLock();
  }
}

/**
 * ==============================================================================
 * 3. HÀM XỬ LÝ KHI THẦY BẤM NÚT XÁC NHẬN THANH TOÁN TRONG GMAIL
 * ==============================================================================
 */
function handleConfirmPayment(token, rowStr) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
    var lastRow = sheet.getLastRow();
    var rowIndex = parseInt(rowStr);
    var targetRow = -1;

    // Tìm hàng theo rowIndex và kiểm tra token
    if (rowIndex && rowIndex >= 2 && rowIndex <= lastRow) {
      var rowToken = sheet.getRange(rowIndex, 14).getValue();
      if (rowToken == token) {
        targetRow = rowIndex;
      }
    }

    // Quét toàn bộ cột 14 nếu thứ tự hàng bị thay đổi
    if (targetRow === -1 && token && lastRow >= 2) {
      var data = sheet.getRange(2, 14, lastRow - 1, 1).getValues();
      for (var i = 0; i < data.length; i++) {
        if (data[i][0] == token) {
          targetRow = i + 2;
          break;
        }
      }
    }

    if (targetRow === -1) {
      return renderHtmlResponse({
        success: false,
        title: "Không tìm thấy đơn đăng ký!",
        message: "Mã xác thực không khớp hoặc đơn này đã bị xóa khỏi Google Sheet."
      });
    }

    // Đọc thông tin học viên từ Sheet
    var rowData = sheet.getRange(targetRow, 1, 1, 14).getValues()[0];
    var parentName = rowData[1];
    var phone = rowData[2];
    var email = rowData[3];
    var studentInfo = rowData[4];
    var studentCount = rowData[5];
    var selectedModules = rowData[6];
    var totalSessions = rowData[7];
    var totalPrice = rowData[9];
    var currentStatus = rowData[12] ? rowData[12].toString() : "";

    // Nếu đơn này đã được bấm xác nhận trước đó
    if (currentStatus.indexOf("ĐÃ THANH TOÁN") !== -1) {
      return renderHtmlResponse({
        success: true,
        alreadyConfirmed: true,
        title: "Đơn Này Đã Được Xác Nhận Trước Đó!",
        message: "Học viên <strong>" + studentInfo + "</strong> (PH: " + parentName + ") đã được xác nhận thanh toán thành công trước đó. Email chúc mừng và link Zalo đã được gửi cho gia đình.",
        parentName: parentName,
        studentInfo: studentInfo,
        phone: phone,
        email: email,
        totalPrice: totalPrice,
        status: currentStatus
      });
    }

    // Cập nhật trạng thái thành công lên Google Sheet
    var nowFormatted = Utilities.formatDate(new Date(), "GMT+7", "dd/MM/yyyy HH:mm");
    var updatedStatus = "✅ ĐÃ THANH TOÁN (" + nowFormatted + ")";
    sheet.getRange(targetRow, 13).setValue(updatedStatus);
    sheet.getRange(targetRow, 13).setBackground("#DCFCE7").setFontColor("#15803D").setFontWeight("bold");

    // Gửi THƯ CHÚC MỪNG GHI DANH KÈM LINK & MÃ QR NHÓM ZALO CHO PHỤ HUYNH
    var emailSent = false;
    if (email && email.indexOf("@") !== -1) {
      sendOfficialEnrollmentEmail(email, {
        parentName: parentName,
        phone: phone,
        studentInfo: studentInfo,
        studentCount: studentCount,
        selectedModules: selectedModules,
        totalSessions: totalSessions,
        totalPrice: totalPrice,
        paymentDate: nowFormatted
      });
      emailSent = true;
    }

    return renderHtmlResponse({
      success: true,
      title: "XÁC NHẬN THANH TOÁN THÀNH CÔNG! 🎉",
      message: "Đã cập nhật trạng thái trên Google Sheet và tự động gửi Thư Chúc Mừng Ghi Danh kèm Link & Mã QR Nhóm Zalo cho phụ huynh.",
      parentName: parentName,
      studentInfo: studentInfo,
      phone: phone,
      email: email,
      totalPrice: totalPrice,
      status: updatedStatus,
      emailSent: emailSent
    });

  } catch (err) {
    return renderHtmlResponse({
      success: false,
      title: "Có lỗi xảy ra!",
      message: err.toString()
    });
  } finally {
    lock.releaseLock();
  }
}

