/**
 * ==============================================================================
 * 8. TỰ ĐỘNG KHỞI TẠO TIÊU ĐỀ SHEET NẾU CÒN TRỐNG
 * ==============================================================================
 */
function setupHeadersIfEmpty(sheet) {
  if (sheet.getLastRow() === 0) {
    var headers = [
      "Thời Gian Đăng Ký",
      "Họ Tên Phụ Huynh",
      "Số Điện Thoại / Zalo",
      "Email Phụ Huynh",
      "Tên Học Sinh & Lớp",
      "Số Lượng Bé",
      "Các Module Đã Chọn",
      "Tổng Số Buổi",
      "Đơn Giá/Buổi/Bé (VNĐ)",
      "Tổng Học Phí (VNĐ)",
      "Mức Tiết Kiệm (VNĐ)",
      "Nhu Cầu / Ghi Chú Của Bé",
      "Trạng Thái Xử Lý",
      "Mã Token Xác Nhận"
    ];
    sheet.appendRow(headers);
    var headerRange = sheet.getRange(1, 1, 1, headers.length);
    headerRange.setBackground("#0F172A").setFontColor("#38BDF8").setFontWeight("bold").setHorizontalAlignment("center");
    sheet.setFrozenRows(1);
  } else {
    // Đảm bảo cột 14 có tiêu đề Token
    if (sheet.getRange(1, 14).getValue() === "") {
      sheet.getRange(1, 14).setValue("Mã Token Xác Nhận").setBackground("#0F172A").setFontColor("#38BDF8").setFontWeight("bold").setHorizontalAlignment("center");
    }
  }
}
